#!/usr/bin/env python3
import subprocess, sys, os, json

REF = "/tmp/ref/crowbook"
BOOK = "/tmp/work/tpl11/b1/book.md"
D = "/tmp/work/tpl11/b1"

def render(opt, tplbody, extra=None, fmt="html", outname="probe_out"):
    tpl = os.path.join(D, "probe.tpl")
    with open(tpl, "w") as f:
        f.write(tplbody)
    out = os.path.join(D, outname)
    if os.path.isdir(out):
        pass
    elif os.path.exists(out):
        os.remove(out)
    cmd = [REF, BOOK, "-t", fmt, "-o", out, "--set", opt, tpl]
    if extra:
        cmd += extra
    p = subprocess.run(cmd, capture_output=True, text=True, cwd=D)
    txt = None
    if os.path.exists(out) and os.path.isfile(out):
        txt = open(out, encoding="utf-8", errors="replace").read()
    return p.returncode, p.stdout, p.stderr, txt

def probe_names(opt, names, fmt="html", extra=None, expr="{{%s}}", outname="probe_out"):
    res = {}
    for n in names:
        rc, so, se, txt = render(opt, "\x01" + (expr % n) + "\x02", extra=extra, fmt=fmt, outname=outname)
        if txt is not None and "\x01" in txt:
            i = txt.index("\x01"); j = txt.index("\x02")
            res[n] = ("OK", txt[i+1:j])
        else:
            err = (se or "") + (so or "")
            reason = "?"
            for line in err.splitlines():
                line = line.strip()
                if line.startswith("= reason:"):
                    reason = line[len("= reason:"):].strip()
            res[n] = ("ERR", reason)
    return res

if __name__ == "__main__":
    opt = sys.argv[1]
    fmt = sys.argv[2]
    names = sys.argv[3:]
    r = probe_names(opt, names, fmt=fmt)
    for n in names:
        k, v = r[n]
        print("%-28s %-4s %r" % (n, k, v))

