#!/usr/bin/env python3
import subprocess, sys, os, shutil, glob

REF = "/tmp/ref/crowbook"

def run(book, sets, fmt, out, cwd=None):
    D = cwd or os.path.dirname(book)
    cmd = [REF, os.path.basename(book), "-t", fmt, "-o", out, "--set"] + sets
    p = subprocess.run(cmd, capture_output=True, text=True, cwd=D)
    return p

def reason(p):
    err = (p.stderr or "") + (p.stdout or "")
    for line in err.splitlines():
        line = line.strip()
        if line.startswith("= reason:"):
            return line[len("= reason:"):].strip()
    lines = [l.strip() for l in err.splitlines() if l.strip() and not l.startswith("CROWBOOK")]
    return " | ".join(lines)[:300] or "?"

def extract(text):
    if text is None or "\x01" not in text:
        return None
    i = text.index("\x01"); j = text.index("\x02")
    return text[i+1:j]

def probe_dir(book, opt, names, expr="{{%s}}", which=0, trunc=90, sets=None):
    D = os.path.dirname(book)
    tpl = os.path.join(D, "probe.tpl")
    outd = os.path.join(D, "probe_dir")
    for n in names:
        open(tpl, "w").write("\x01" + (expr % n) + "\x02")
        if os.path.isdir(outd):
            shutil.rmtree(outd)
        p = run(book, [opt, "probe.tpl"] + (sets or []), "html.dir", "probe_dir")
        vals = []
        for f in sorted(glob.glob(os.path.join(outd, "*.html"))):
            v = extract(open(f, encoding="utf-8", errors="replace").read())
            vals.append((os.path.basename(f), v))
        if vals and any(v is not None for _, v in vals):
            out = "; ".join("%s=%r" % (a, (b[:trunc] + "..." if b and len(b) > trunc else b)) for a, b in vals)
            print("%-26s OK   %s" % (n, out[:400]))
        else:
            print("%-26s ERR  %s" % (n, reason(p)))

def probe_epub(book, opt, names, expr="{{%s}}", trunc=90, sets=None, want=None):
    import zipfile
    D = os.path.dirname(book)
    tpl = os.path.join(D, "probe.tpl")
    outf = os.path.join(D, "probe.epub")
    for n in names:
        open(tpl, "w").write("\x01" + (expr % n) + "\x02")
        if os.path.exists(outf):
            os.remove(outf)
        p = run(book, [opt, "probe.tpl"] + (sets or []), "epub", "probe.epub")
        vals = []
        if os.path.exists(outf):
            try:
                z = zipfile.ZipFile(outf)
                for nm in z.namelist():
                    if nm.endswith(".xhtml") or nm.endswith(".html") or nm.endswith(".css"):
                        if want and want not in nm:
                            continue
                        v = extract(z.read(nm).decode("utf-8", "replace"))
                        if v is not None:
                            vals.append((nm, v))
            except Exception as e:
                print("%-26s ZIPERR %s" % (n, e)); continue
        if vals:
            out = "; ".join("%s=%r" % (a, (b[:trunc] + "..." if len(b) > trunc else b)) for a, b in vals)
            print("%-26s OK   %s" % (n, out[:500]))
        else:
            print("%-26s ERR  %s" % (n, reason(p)))

